# Pytest unit tests with fixtures and parametrization
import pytest

@pytest.fixture
def sample_user_record():
    return {'name': 'Rohan', 'balance': 500.0, 'is_active': True}

@pytest.mark.parametrize('withdrawal, expected_balance', [
    (100.0, 400.0),
    (500.0, 0.0),
])
def test_valid_withdrawals(sample_user_record, withdrawal, expected_balance):
    sample_user_record['balance'] -= withdrawal
    assert sample_user_record['balance'] == expected_balance

def test_insufficient_balance(sample_user_record):
    with pytest.raises(ValueError, match='Insufficient'):
        if sample_user_record['balance'] < 600.0:
            raise ValueError('Insufficient funds.')

