# Modular APIRouter with Dependency Injection
from fastapi import APIRouter, Depends, Query
from pydantic import BaseModel

router = APIRouter(prefix='/products', tags=['Products'])

class PaginationParams:
    def __init__(self, page: int = Query(1, ge=1), size: int = Query(20, ge=1, le=100)):
        self.skip = (page - 1) * size
        self.limit = size

@router.get('/')
def list_products(pagination: PaginationParams = Depends()):
    return {'skip': pagination.skip, 'limit': pagination.limit, 'data': []}

